        let b: Uint<4> = Uint::new([4, 0, 0, 0]);
        assert!(a.ge(&b));
        assert!(a.gt(&b));
        assert!(!a.le(&b));
        assert!(!a.lt(&b));
        assert!(!a.eq(&b));
