453	impl<'a, P: SWCurveConfig> AddAssign<&'a Self> for Projective<P> {
454	    fn add_assign(&mut self, other: &'a Self) {
455	        if self.is_zero() {
456	            *self = *other;
457	            return;
458	        }
459	
460	        if other.is_zero() {
461	            return;
462	        }
463	
464	        // http://www.hyperelliptic.org/EFD/g1p/auto-shortw-jacobian-0.html#addition-add-2007-bl
465	        // Works for all curves.
466	
467	        // Z1Z1 = Z1^2
468	        let z1z1 = self.z.square();
469	
470	        // Z2Z2 = Z2^2
471	        let z2z2 = other.z.square();
472	
473	        // U1 = X1*Z2Z2
474	        let mut u1 = self.x;
475	        u1 *= &z2z2;
476	
477	        // U2 = X2*Z1Z1
478	        let mut u2 = other.x;
479	        u2 *= &z1z1;
480	
481	        // S1 = Y1*Z2*Z2Z2
482	        let mut s1 = self.y;
483	        s1 *= &other.z;
484	        s1 *= &z2z2;
485	
486	        // S2 = Y2*Z1*Z1Z1
487	        let mut s2 = other.y;
488	        s2 *= &self.z;
489	        s2 *= &z1z1;
490	
491	        if u1 == u2 {
492	            if s1 == s2 {
493	                // The two points are equal, so we double.
494	                self.double_in_place();
495	            } else {
496	                // a + (-a) = 0
497	                *self = Self::zero();
498	            }
499	        } else {
500	            // H = U2-U1
501	            let mut h = u2;
502	            h -= &u1;
503	
504	            // I = (2*H)^2
505	            let mut i = h;
506	            i.double_in_place().square_in_place();
507	
508	            // J = -H*I
509	            let mut j = h;
510	            j.neg_in_place();
511	            j *= &i;
512	
513	            // r = 2*(S2-S1)
514	            let mut r = s2;
515	            r -= &s1;
516	            r.double_in_place();
517	
518	            // V = U1*I
519	            let mut v = u1;
520	            v *= &i;
521	
522	            // X3 = r^2 + J - 2*V
523	            self.x = r;
524	            self.x.square_in_place();
525	            self.x += &j;
526	            self.x -= &(v.double());
527	
528	            // Y3 = r*(V - X3) + 2*S1*J
529	            v -= &self.x;
530	            self.y = s1;
531	            self.y.double_in_place();
532	            self.y = P::BaseField::sum_of_products(&[r, self.y], &[v, j]);
533	
534	            // Z3 = ((Z1+Z2)^2 - Z1Z1 - Z2Z2)*H
535	            // This is equal to Z3 = 2 * Z1 * Z2 * H, and computing it this way
536	            // is faster.
