 30	/// Elliptic curves can be represented via different "models" with varying
 31	/// efficiency properties.
 32	///
 33	/// [`CurveConfig`] bundles together the types that are common
 34	/// to all models of the given curve, namely the [`Self::BaseField`] over which
 35	/// the curve is defined, and the [`Self::ScalarField`] defined by the
 36	/// appropriate prime-order subgroup of the curve.
 37	pub trait CurveConfig: Send + Sync + Sized + 'static {
 38	    /// Base field that the curve is defined over.
 39	    type BaseField: Field;
 40	    /// Finite prime field corresponding to an appropriate prime-order subgroup
 41	    /// of the curve group.
 42	    type ScalarField: PrimeField;
 43	
 44	    /// The cofactor of this curve, represented as a sequence of little-endian
 45	    /// limbs.
 46	    const COFACTOR: &'static [u64];
 47	
 48	    /// The inverse of the cofactor.
 49	    const COFACTOR_INV: Self::ScalarField;
 50	
 51	    /// Returns `true` if the cofactor is one.
 52	    fn cofactor_is_one() -> bool {
 53	        let mut iter = Self::COFACTOR.iter();
 54	        matches!(iter.next(), Some(1)) && iter.all(Zero::is_zero)
 55	    }
 56	}
 57	
 58	/// Represents (elements of) a group of prime order `r`.
 59	pub trait PrimeGroup: AdditiveGroup<Scalar = Self::ScalarField> {
 60	    /// The scalar field `F_r`, where `r` is the order of this group.
 61	    type ScalarField: PrimeField;
 62	
 63	    /// Returns a fixed generator of this group.
 64	    #[must_use]
 65	    fn generator() -> Self;
 66	
 67	    /// Performs scalar multiplication of this element.
 68	    #[must_use]
 69	    fn mul_bigint(&self, other: impl BitIteratorBE) -> Self;
 70	
 71	    /// Computes `other * self`, where `other` is a *big-endian*
 72	    /// bit representation of some integer.
 73	    #[must_use]
 74	    fn mul_bits_be(&self, other: impl Iterator<Item = bool>) -> Self {
 75	        let mut res = Self::zero();
 76	        for b in other.skip_while(|b| !b) {
 77	            // skip leading zeros
 78	            res.double_in_place();
 79	            if b {
 80	                res += self;
 81	            }
 82	        }
 83	        res
 84	    }
 85	}
 86	
 87	/// An opaque representation of an elliptic curve group element that is suitable
 88	/// for efficient group arithmetic.
 89	///
 90	/// The point is guaranteed to be in the correct prime order subgroup.
 91	pub trait CurveGroup:
 92	    PrimeGroup
 93	    + Add<Self::Affine, Output = Self>
 94	    + AddAssign<Self::Affine>
 95	    + Sub<Self::Affine, Output = Self>
 96	    + SubAssign<Self::Affine>
 97	    + From<Self::Affine>
 98	    + Into<Self::Affine>
 99	    + core::iter::Sum<Self::Affine>
100	    + for<'a> core::iter::Sum<&'a Self::Affine>
101	{
102	    /// Associated configuration for this curve.
103	    type Config: CurveConfig<
104	        ScalarField = Self::ScalarField,
105	        BaseField = Self::BaseField,
106	    >;
107	
108	    /// The field over which this curve is defined.
109	    type BaseField: Field;
110	
111	    /// The affine representation of this element.
112	    type Affine: AffineRepr<
113	            Config = Self::Config,
114	            Group = Self,
115	            ScalarField = Self::ScalarField,
116	            BaseField = Self::BaseField,
117	        > + From<Self>
118	        + Into<Self>;
119	
120	    /// Type representing an element of the full elliptic curve group, not just
121	    /// the prime order subgroup.
122	    type FullGroup;
123	
124	    /// Normalizes a slice of group elements into affine.
125	    #[must_use]
126	    fn normalize_batch(v: &[Self]) -> Vec<Self::Affine>;
127	
128	    /// Converts `self` into the affine representation.
129	    fn into_affine(self) -> Self::Affine {
130	        self.into()
131	    }
132	}
