134	/// The canonical representation of an elliptic curve group element.
135	/// This should represent the affine coordinates of the point corresponding
136	/// to this group element.
137	///
138	/// The point is guaranteed to be in the correct prime order subgroup.
139	pub trait AffineRepr:
140	    Eq
141	    + 'static
142	    + Sized
143	    + Copy
144	    + Clone
145	    + Default
146	    + Send
147	    + Sync
148	    + Hash
149	    + Debug
150	    + Display
151	    + Zeroize
152	    + Neg
153	    + From<<Self as AffineRepr>::Group>
154	    + Into<<Self as AffineRepr>::Group>
155	    + Add<Self, Output = Self::Group>
156	    + for<'a> Add<&'a Self, Output = Self::Group>
157	    + Add<Self::Group, Output = Self::Group>
158	    + for<'a> Add<&'a Self::Group, Output = Self::Group>
159	    + Sub<Self, Output = Self::Group>
160	    + for<'a> Sub<&'a Self, Output = Self::Group>
161	    + Sub<Self::Group, Output = Self::Group>
162	    + for<'a> Sub<&'a Self::Group, Output = Self::Group>
163	    + Mul<Self::ScalarField, Output = Self::Group>
164	    + for<'a> Mul<&'a Self::ScalarField, Output = Self::Group>
165	{
166	    /// Associated configuration for this curve.
167	    type Config: CurveConfig<
168	        ScalarField = Self::ScalarField,
169	        BaseField = Self::BaseField,
170	    >;
171	
172	    /// Finite prime field corresponding to an appropriate prime-order subgroup
173	    /// of the curve group.
174	    type ScalarField: PrimeField;
175	
176	    /// Base field that the curve is defined over.
177	    type BaseField: Field;
178	
179	    /// The projective representation of points on this curve.
180	    type Group: CurveGroup<
181	            Config = Self::Config,
182	            Affine = Self,
183	            ScalarField = Self::ScalarField,
184	            BaseField = Self::BaseField,
185	        > + From<Self>
186	        + Into<Self>
187	        + MulAssign<Self::ScalarField>; // needed due to https://github.com/rust-lang/rust/issues/69640
188	
189	    /// Returns the x and y coordinates of this affine point.
190	    fn xy(&self) -> Option<(Self::BaseField, Self::BaseField)>;
191	
192	    /// Returns the x coordinate of this affine point.
193	    fn x(&self) -> Option<Self::BaseField> {
194	        self.xy().map(|(x, _)| x)
195	    }
196	
197	    /// Returns the y coordinate of this affine point.
198	    fn y(&self) -> Option<Self::BaseField> {
199	        self.xy().map(|(_, y)| y)
200	    }
201	
202	    /// Returns the point at infinity.
203	    fn zero() -> Self;
204	
205	    /// Is `self` the point at infinity?
206	    fn is_zero(&self) -> bool {
207	        self.xy().is_none()
208	    }
209	
210	    /// Returns a fixed generator of unknown exponent.
211	    #[must_use]
212	    fn generator() -> Self;
213	
214	    /// Converts self into the projective representation.
215	    fn into_group(self) -> Self::Group {
216	        self.into()
217	    }
218	
219	    /// Performs scalar multiplication of this element with mixed addition.
220	    #[must_use]
221	    fn mul_bigint(&self, by: impl BitIteratorBE) -> Self::Group;
222	
223	    /// Performs cofactor clearing.
224	    /// The default method is simply to multiply by the cofactor.
225	    /// For some curve families more efficient methods exist.
226	    #[must_use]
227	    fn clear_cofactor(&self) -> Self;
228	
229	    /// Multiplies this element by the cofactor and output the
230	    /// resulting projective element.
231	    #[must_use]
232	    fn mul_by_cofactor_to_group(&self) -> Self::Group;
233	
234	    /// Multiplies this element by the cofactor.
235	    #[must_use]
236	    fn mul_by_cofactor(&self) -> Self {
237	        self.mul_by_cofactor_to_group().into()
238	    }
239	
240	    /// Multiplies this element by the inverse of the cofactor in
241	    /// `Self::ScalarField`.
242	    #[must_use]
243	    fn mul_by_cofactor_inv(&self) -> Self {
244	        self.mul_bigint(Self::Config::COFACTOR_INV.into_bigint()).into()
245	    }
246	}
