 30	/// Elliptic curves can be represented via different "models" with varying
 31	/// efficiency properties.
 32	///
 33	/// [`CurveConfig`] bundles together the types that are common
 34	/// to all models of the given curve, namely the [`Self::BaseField`] over which
 35	/// the curve is defined, and the [`Self::ScalarField`] defined by the
 36	/// appropriate prime-order subgroup of the curve.
 37	pub trait CurveConfig: Send + Sync + Sized + 'static {
 38	    /// Base field that the curve is defined over.
 39	    type BaseField: Field;
 40	    /// Finite prime field corresponding to an appropriate prime-order subgroup
 41	    /// of the curve group.
 42	    type ScalarField: PrimeField;
 43	
 44	    /// The cofactor of this curve, represented as a sequence of little-endian
 45	    /// limbs.
 46	    const COFACTOR: &'static [u64];
 47	
 48	    /// The inverse of the cofactor.
 49	    const COFACTOR_INV: Self::ScalarField;
 50	
 51	    /// Returns `true` if the cofactor is one.
 52	    fn cofactor_is_one() -> bool {
 53	        let mut iter = Self::COFACTOR.iter();
 54	        matches!(iter.next(), Some(1)) && iter.all(Zero::is_zero)
 55	    }
 56	}
