261	/// Efficiently computes `coeff * v_i^(-1)` for each non-zero element.
262	///
263	/// Optimizes batch inversion by multiplying each result by a coefficient.
264	/// Implements Montgomery's trick in two passes to minimize field inversions.
265	/// Zero elements remain unchanged.
266	///
267	/// # Arguments
268	///
269	/// * `v` - Mutable slice for in-place computation.
270	/// * `coeff` - Coefficient to multiply each inverse by.
271	fn batch_inversion_and_mul<F: Field>(v: &mut [F], coeff: &F) {
272	    // Montgomery's Trick and Fast Implementation of Masked AES
273	    // Genelle, Prouff and Quisquater
274	    // Section 3.2
275	    // but with an optimization to multiply every element in the returned vector
 25	#[must_use]
 26	pub struct Affine<P: TECurveConfig> {
 27	    /// X coordinate of the point represented as a field element
 28	    pub x: P::BaseField,
 29	    /// Y coordinate of the point represented as a field element
 30	    pub y: P::BaseField,
 31	}
