334	        // A = x1 * x2
335	        let a = self.x * other.x;
336	
337	        // B = y1 * y2
338	        let b = self.y * other.y;
339	
340	        // C = d * t1 * t2
341	        let c = P::COEFF_D * self.t * other.t;
