343	        // D = z1 * z2
344	        let d = self.z * other.z;
345	
346	        // H = B - aA
347	        let h = b - P::mul_by_a(a);
348	
349	        // E = (x1 + y1) * (x2 + y2) - A - B
350	        let e = (self.x + self.y) * (other.x + other.y) - a - b;
351	
352	        // F = D - C
353	        let f = d - c;
354	
355	        // G = D + C
356	        let g = d + c;
357	
358	        // x3 = E * F
359	        self.x = e * f;
360	
361	        // y3 = G * H
362	        self.y = g * h;
363	
364	        // t3 = E * H
365	        self.t = e * h;
366	
367	        // z3 = F * G
