 29	fn check_sw_group<P: SWCurveConfig>(left: u64, right: u64, scale: u8) {
 30	    let generator = SWAffine::<P>::generator();
 31	    let left_point = generator.mul_bigint(left);
 32	    let right_point = generator.mul_bigint(right);
 33	    let expected = generator.mul_bigint(left + right);
 34	    let expected_difference = if left >= right {
 35	        generator.mul_bigint(left - right)
 36	    } else {
 37	        -generator.mul_bigint(right - left)
 38	    };
 39	
 40	    // The group law must agree across affine, mixed, projective and scalar
 41	    // multiplication APIs, including identity and inverse cases.
 42	    assert_eq!(left_point + right_point, expected);
 43	    assert_eq!(left_point + right_point.into_affine(), expected);
 44	    assert_eq!(left_point - right_point, expected_difference);
 45	    assert_eq!(left_point + -left_point, SWProjective::<P>::zero());
 46	    assert_eq!(left_point + SWProjective::<P>::zero(), left_point);
 47	    assert_eq!(SWProjective::<P>::zero() + left_point, left_point);
 48	    assert_eq!(left_point + SWAffine::<P>::zero(), left_point);
 49	    assert_eq!(SWAffine::<P>::zero() + left_point, left_point);
 50	
 51	    let mut doubled = left_point;
 52	    doubled.double_in_place();
 53	    assert_eq!(doubled, left_point + left_point);
 54	    assert_eq!(left_point.double(), left_point + left_point);
 55	
 56	    let left_affine = left_point.into_affine();
 57	    assert_eq!(
 58	        left_affine.xy(),
 59	        (!left_affine.infinity).then_some((left_affine.x, left_affine.y))
 60	    );
 61	    assert_eq!(left_affine.is_zero(), left == 0);
 62	    assert_eq!(left_affine.into_group(), left_point);
 63	    assert_eq!(SWProjective::<P>::from(left_affine).into_affine(), left_affine);
 64	
 65	    // Equivalent Jacobian triples use X/Z^2 and Y/Z^3.
 66	    let scale = P::BaseField::from(u64::from(scale.max(1)));
 67	    let scale_squared = scale.square();
 68	    let scaled = SWProjective::<P>::new_unchecked(
 69	        left_point.x * scale_squared,
 70	        left_point.y * scale_squared * scale,
 71	        left_point.z * scale,
 72	    );
 73	    assert_eq!(scaled, left_point);
 74	    assert_eq!(scaled.into_affine(), left_affine);
 75	
 76	    let normalized = SWProjective::<P>::normalize_batch(&[
 77	        SWProjective::<P>::zero(),
 78	        left_point,
 79	        scaled,
 80	    ]);
 81	    assert_eq!(normalized, [SWAffine::<P>::zero(), left_affine, left_affine]);
 82	    assert!(SWProjective::<P>::normalize_batch(&[]).is_empty());
 83	
 84	    // Exercise the reference-forwarding operator implementations as well as
 85	    // the standard owned operators.
 86	    let mut right_copy = right_point;
 87	    assert_eq!(&left_point + right_point, expected);
 88	    assert_eq!(&left_point + &right_point, expected);
 89	    assert_eq!(&left_point + &mut right_copy, expected);
 90	    assert_eq!(left_point + &mut right_copy, expected);
 91	    assert_eq!(&left_point - right_point, expected_difference);
 92	    assert_eq!(&left_point - &right_point, expected_difference);
 93	    assert_eq!(&left_point - &mut right_copy, expected_difference);
 94	
 95	    let mut assigned = left_point;
 96	    assigned += right_point;
 97	    assert_eq!(assigned, expected);
 98	    assigned -= right_point;
 99	    assert_eq!(assigned, left_point);
100	    let mut assigned_mut = left_point;
101	    let mut rhs_mut = right_point;
102	    assigned_mut += &mut rhs_mut;
103	    assert_eq!(assigned_mut, expected);
104	    assigned_mut -= &mut rhs_mut;
105	    assert_eq!(assigned_mut, left_point);
106	
107	    let affine_sum: SWProjective<P> =
108	        [left_affine, right_point.into_affine()].into_iter().sum();
109	    assert_eq!(affine_sum, expected);
110	    let affine_ref_sum: SWProjective<P> =
111	        [&left_affine, &right_point.into_affine()].into_iter().sum();
112	    assert_eq!(affine_ref_sum, expected);
113	    let projective_ref_sum: SWProjective<P> =
114	        [&left_point, &right_point].into_iter().sum();
115	    assert_eq!(projective_ref_sum, expected);
116	
117	    assert_eq!(
118	        left_point * P::ScalarField::from(0u64),
119	        SWProjective::<P>::zero()
120	    );
121	    assert_eq!(left_point * P::ScalarField::from(1u64), left_point);
122	    assert_eq!(
123	        left_point * P::ScalarField::from(2u64),
124	        left_point + left_point
125	    );
126	}
