1145	    /// Compute the `i`-th bit of `self`.
1146	    #[must_use]
1147	    pub const fn get_bit(&self, i: usize) -> bool {
1148	        if i >= Uint::<N>::BITS {
1149	            self.high.get_bit(i - Uint::<N>::BITS)
1150	        } else {
1151	            self.low.get_bit(i)
1152	        }
1153	    }
