            Fp::<P, N>::mul(
                &r,
                &Fp { montgomery_form: P::R2, phantom: PhantomData },
            )
        }
    }

    }

    #[inline]
    fn neg_in_place(&mut self) -> &mut Self {
        P::neg_in_place(self);
        self
    }
}

