    assert!(generator.is_on_curve());
    assert_eq!(generator.x(), Some(generator.x));
    assert_eq!(generator.y(), Some(generator.y));
    assert_eq!(generator.xy(), Some((generator.x, generator.y)));
    assert_eq!(
        format!("{generator}"),
        format!("({}, {})", generator.x, generator.y)
    );
    assert_eq!(
        format!("{generator:?}"),
